const BASE_BACKOFF_MS = 500;     // smaller initial back‑off
const JITTER = 0.2;              // add randomness

async function fetchSupplierFeed() {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), MAX_TIMEOUT_MS);

  try {
    const resp = await fetch('https://supplier.example.com/feed', {
